import XCTest

class ReconTests: XCTestCase {
    func testRecon() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        sleep(2)
        let home = app.debugDescription
        try home.write(toFile: "/tmp/hier_home.txt", atomically: true, encoding: .utf8)
        let room = app.staticTexts["Weekend Plans"].firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 10))
        room.tap()
        sleep(3)
        let roomHier = app.debugDescription
        try roomHier.write(toFile: "/tmp/hier_room.txt", atomically: true, encoding: .utf8)
    }
}
