import XCTest

class ReconTests: XCTestCase {
    func testRecon() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 3)
        try app.debugDescription.write(toFile: "/tmp/hier_home.txt", atomically: true, encoding: .utf8)

        let room = app.staticTexts["Weekend Plans"].firstMatch
        XCTAssertTrue(room.waitForExistence(timeout: 10), "Weekend Plans not found")
        room.tap()
        Thread.sleep(forTimeInterval: 4)
        try app.debugDescription.write(toFile: "/tmp/hier_room.txt", atomically: true, encoding: .utf8)
    }
}

import XCTest

class SendTests: XCTestCase {
    func testSend() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let gotIt = app.buttons["Got it"]
        if gotIt.waitForExistence(timeout: 5) {
            gotIt.tap()
            Thread.sleep(forTimeInterval: 1)
        }

        if !app.textFields["DisplayNameTextField"].waitForExistence(timeout: 5) {
            let room = app.staticTexts["Weekend Plans"].firstMatch
            XCTAssertTrue(room.waitForExistence(timeout: 10))
            room.tap()
            XCTAssertTrue(app.textFields["DisplayNameTextField"].waitForExistence(timeout: 10))
        }

        let composer = app.textViews["GrowingTextView"]
        XCTAssertTrue(composer.waitForExistence(timeout: 10))
        composer.tap()
        Thread.sleep(forTimeInterval: 1)
        composer.typeText("benchmark test")

        let send = app.buttons["SendButton"]
        let enabled = NSPredicate(format: "isEnabled == true")
        expectation(for: enabled, evaluatedWith: send, handler: nil)
        waitForExpectations(timeout: 10)
        send.tap()

        let sent = app.textViews["MessageTextView"].matching(NSPredicate(format: "value CONTAINS %@", "benchmark test")).firstMatch
        XCTAssertTrue(sent.waitForExistence(timeout: 10), "sent message not visible")
        Thread.sleep(forTimeInterval: 2)
        try app.debugDescription.write(toFile: "/tmp/hier_sent.txt", atomically: true, encoding: .utf8)
    }
}
